  it('keeps the usage an earlier round reported when a later round reports none', async () => {
    const usage: UsageMetadata = {inputTokens: 11, outputTokens: 3, totalTokens: 14};
    let seen: UsageMetadata | undefined;
    const hooks: OrchestratorHooks = {
      afterModelResponse: async (_session, _text, reported) => {
        seen = reported;
      },
    };
    const orchestrator = createChatOrchestrator(
      scriptedProvider([
        [TOOL_CALL, {type: 'stop', stopReason: 'tool_use', usage}],
        [{type: 'text', text: 'done'}, STOP_DONE],
      ]),
      promptBuilder,
      registryReturning({result: 'r'}),
      {hooks}
    );

    await orchestrator.processMessage(createSession('ask'));

    expect(seen).toEqual(usage);
  });

  it('returns a rejected tool call to the model as a tool_result that the model can correct', async () => {
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'action',
        description: 'Action tool',
        inputSchema: {
          type: 'object',
          properties: {operation: {type: 'string', enum: ['create', 'update', 'delete']}},
          required: ['operation'],
        },
      },
      async () => 'success'
    );

    // Provider asks for a tool with invalid input, then corrects it
    const provider = scriptedProvider([
      [{type: 'tool_use', toolCall: {id: 'call-1', name: 'action', input: {operation: 'invalid'}}}, STOP_FOR_TOOL],
      [{type: 'tool_use', toolCall: {id: 'call-2', name: 'action', input: {operation: 'create'}}}, STOP_FOR_TOOL],
      [{type: 'text', text: 'action created'}, STOP_DONE],
    ]);

    const orchestrator = createChatOrchestrator(provider, promptBuilder, registry);
    const result = await orchestrator.processMessage(createSession('do something'));

    expect(result).toBe('action created');
  });
});

